"""The charts are generated by tools/generate_charts.py; these pin the cells
that the standard published charts are known for, plus the rule fallbacks."""

import pytest

from bjtrainer.cards import Hand, card, hand
from bjtrainer.drills import CELLS, cards_for_cell, key_for_cell
from bjtrainer.strategy import (
    DOUBLE,
    HIT,
    SPLIT,
    STAND,
    SURRENDER,
    Rules,
    basic_action,
    chart_code,
)
import random

S17 = Rules()
H17 = Rules(h17=True)
NO_SUR = Rules(surrender=False)
NO_DAS = Rules(das=False)

# (hand, dealer upcard, rules, expected action)
CANONICAL = [
    # Hard totals
    ("T6", "9", S17, SURRENDER), ("T6", "9", NO_SUR, HIT),
    ("T6", "T", S17, SURRENDER), ("T6", "T", NO_SUR, HIT),
    ("T6", "7", S17, HIT),       ("T6", "6", S17, STAND),
    ("T5", "T", S17, SURRENDER), ("T5", "T", NO_SUR, HIT),
    ("T5", "A", S17, HIT),       ("T5", "A", H17, SURRENDER),
    ("T7", "A", S17, STAND),     ("T7", "A", H17, SURRENDER),
    ("T2", "2", S17, HIT),       ("T2", "3", S17, HIT),
    ("T2", "4", S17, STAND),     ("T2", "6", S17, STAND),
    ("T3", "2", S17, STAND),     ("T4", "7", S17, HIT),
    ("54", "2", S17, HIT),       ("54", "3", S17, DOUBLE),
    ("54", "7", S17, HIT),
    ("64", "9", S17, DOUBLE),    ("64", "T", S17, HIT),
    ("65", "T", S17, DOUBLE),    ("65", "A", S17, HIT),
    ("65", "A", H17, DOUBLE),
    ("T8", "T", S17, STAND),     ("32", "5", S17, HIT),
    # Soft totals
    ("A2", "4", S17, HIT),       ("A2", "5", S17, DOUBLE),
    ("A3", "4", S17, HIT),       ("A3", "5", S17, DOUBLE),
    ("A4", "4", S17, DOUBLE),    ("A4", "3", S17, HIT),
    ("A5", "4", S17, DOUBLE),    ("A6", "2", S17, HIT),
    ("A6", "3", S17, DOUBLE),
    ("A7", "2", S17, STAND),     ("A7", "2", H17, DOUBLE),
    ("A7", "6", S17, DOUBLE),    ("A7", "7", S17, STAND),
    ("A7", "9", S17, HIT),       ("A7", "A", S17, HIT),
    ("A8", "6", S17, STAND),     ("A8", "6", H17, DOUBLE),
    ("A9", "6", S17, STAND),
    # Pairs
    ("AA", "T", S17, SPLIT),     ("AA", "A", S17, SPLIT),
    ("TT", "6", S17, STAND),     ("TT", "5", S17, STAND),
    ("99", "7", S17, STAND),     ("99", "8", S17, SPLIT),
    ("99", "T", S17, STAND),     ("99", "A", S17, STAND),
    ("88", "T", S17, SPLIT),     ("88", "A", S17, SPLIT),
    ("88", "A", H17, SURRENDER), ("88", "A", Rules(h17=True, surrender=False), SPLIT),
    ("77", "7", S17, SPLIT),     ("77", "8", S17, HIT),
    ("66", "2", S17, SPLIT),     ("66", "2", NO_DAS, HIT),
    ("66", "7", S17, HIT),
    ("55", "T", S17, HIT),       ("55", "9", S17, DOUBLE),
    ("44", "5", S17, SPLIT),     ("44", "5", NO_DAS, HIT),
    ("44", "4", S17, HIT),
    ("33", "2", S17, SPLIT),     ("33", "2", NO_DAS, HIT),
    ("33", "8", S17, HIT),
    ("22", "3", S17, SPLIT),     ("22", "3", NO_DAS, HIT),
    ("22", "8", S17, HIT),
]


@pytest.mark.parametrize("cards,up,rules,expected", CANONICAL)
def test_canonical_cells(cards, up, rules, expected):
    got = basic_action(hand(cards), card(up), rules)
    assert got == expected, (
        f"{cards} v {up} under {rules.label}: got {got}, expected {expected}"
    )


def test_h17_differs_from_s17_only_where_expected():
    """H17 changes a handful of cells; nothing else should move."""
    differences = set()
    for cards, up in [(c, u) for c, _u, _r, _e in CANONICAL for u in "23456789TA"]:
        if basic_action(hand(cards), card(up), S17) != basic_action(
            hand(cards), card(up), H17
        ):
            differences.add((hand(cards).describe(), up))
    expected = {
        ("hard 11", "A"), ("hard 15", "A"), ("hard 17", "A"),
        ("soft 18", "2"), ("soft 19", "6"), ("pair of 8s", "A"),
    }
    assert differences == expected


def test_ten_valued_cards_are_interchangeable():
    for face in "TJQK":
        assert basic_action(hand(f"6{face}"), card("9"), S17) == SURRENDER
        assert basic_action(hand(f"{face}{face}"), card("6"), S17) == STAND


def test_multi_card_hands_cannot_double_or_surrender():
    three = hand("322")  # hard 7, three cards
    assert basic_action(three, card("5"), S17) == HIT
    # Hard 11 off three cards can no longer double, so it hits.
    assert basic_action(hand("542"), card("6"), S17) == HIT
    # 16 built from three cards cannot be surrendered.
    assert basic_action(hand("664"), card("T"), S17) == HIT


def test_split_hands_respect_das_for_doubling():
    h = Hand(hand("55").cards, from_split=True)
    assert basic_action(h, card("6"), Rules(das=True)) == DOUBLE
    assert basic_action(h, card("6"), Rules(das=False)) == HIT


def test_resplit_limit():
    from bjtrainer.strategy import legality

    assert legality(hand("88"), S17, hands_in_play=1)["can_split"]
    assert not legality(hand("88"), S17, hands_in_play=4)["can_split"]


def test_every_cell_resolves_to_a_legal_action():
    rng = random.Random(3)
    for rules in (S17, H17, NO_SUR, NO_DAS):
        for cell in CELLS:
            player = cards_for_cell(cell, rng)
            up = card("T" if cell[2] == "T" else cell[2])
            action = basic_action(player, up, rules)
            assert action in (HIT, STAND, DOUBLE, SPLIT, SURRENDER)
            if action == SURRENDER:
                assert rules.surrender
            if action == SPLIT:
                assert player.is_pair


def test_cards_for_cell_matches_its_key():
    rng = random.Random(5)
    for cell in CELLS:
        player = cards_for_cell(cell, rng)
        up = card("T" if cell[2] == "T" else cell[2])
        from bjtrainer.drills import cell_key

        assert cell_key(player, up) == key_for_cell(cell)


def test_chart_codes_are_known():
    from bjtrainer.strategy import CODE_NAMES

    rng = random.Random(9)
    for rules in (S17, H17):
        for cell in CELLS:
            code = chart_code(cards_for_cell(cell, rng),
                              card("T" if cell[2] == "T" else cell[2]), rules)
            assert code in CODE_NAMES, code
